package com.ruoyi.ai.mapper;import java.util.List;import org.apache.ibatis.annotations.*;public interface AiConversationMaintenanceMapper{@Select("select c.conversation_id from ai_conversation c where c.update_time < timestampadd(DAY,-#{days},sysdate()) and not exists(select 1 from ai_run r where r.conversation_id=c.conversation_id and r.status in ('RUNNING','WAITING_TOOL','COMPACTING','CANCEL_REQUESTED')) order by c.conversation_id limit 500")List<Long> selectExpiredIds(int days);@Delete("delete from ai_pending_tool_call where conversation_id=#{id}")int deletePending(Long id);@Delete("delete from ai_checkpoint where conversation_id=#{id}")int deleteCheckpoints(Long id);@Delete("delete from ai_message where conversation_id=#{id}")int deleteMessages(Long id);@Delete("delete from ai_run where conversation_id=#{id}")int deleteRuns(Long id);@Delete("delete from ai_conversation where conversation_id=#{id}")int deleteConversation(Long id);}
